 "content": "from collections import deque


def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 5 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                rr, cc = q.popleft()
                cells.append((rr, cc))
                for nr, nc in ((rr-1, cc), (rr+1, cc), (rr, cc-1), (rr, cc+1)):
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 5 and (nr, nc) not in seen:
                        seen.add((nr, nc))
                        q.append((nr, nc))
            r0 = min(x for x, _ in cells)
            r1 = max(x for x, _ in cells)
            c0 = min(y for _, y in cells)
            c1 = max(y for _, y in cells)
            # The frame's single gap is in its top edge; fill the cavity and
            # extend that color leftward along the row just above the frame.
            gaps = [c for c in range(c0, c1 + 1) if grid[r0][c] == 0]
            if len(gaps) == 1 and r1 > r0:
                gap = gaps[0]
                for rr in range(r0, r1 + 1):
                    for cc in range(c0, c1 + 1):
                        if out[rr][cc] == 0:
                            out[rr][cc] = 2
                if r0 > 0:
                    for cc in range(0, gap + 1):
                        if out[r0 - 1][cc] == 0:
                            out[r0 - 1][cc] = 2
    return out
